1: // Raises the "Cursor went quiet" watchdog threshold on the LOADED magpie
2: // cursor plugin (the copy magpie actually imports at runtime), so large
3: // composer 2.5 server-side preps don't trip NATIVE_LIMITS.quiet = 240_000
4: // and end the turn with "Cursor went quiet: N heartbeats and nothing else
5: // for 240 s".
6: //
7: // patch-magpie-quiet.ps1 was meant to do this but resolved its target from
8: // ~/.cache/magpie/bun/install-cache (the unloaded copy), so the change never
9: // took effect. This module is the durable, self-healing equivalent:
10: // reapply.mjs runs it from the scheduled task, so a plugin update that
11: // overwrites native-session.mjs re-raises quiet automatically.
12: //
13: //   node patch-quiet.mjs            apply (idempotent)
14: //   node patch-quiet.mjs --check    exit 0 patched, 3 pristine, 2 missing, 1 unknown
15: //   node patch-quiet.mjs --restore  restore from backup
16: import {
17:   readFileSync,
18:   writeFileSync,
19:   existsSync,
20:   copyFileSync,
21:   renameSync,
22: } from 'node:fs';
23: import { join, dirname } from 'node:path';
24: import { homedir } from 'node:os';
25: import { execSync } from 'node:child_process';
26: import { fileURLToPath } from 'node:url';
27: 
28: export const PATCH_DIR = dirname(fileURLToPath(import.meta.url));
29: export const PLUGIN_DIR = join(
30:   homedir(),
31:   '.config',
32:   'magpie',
33:   'plugins',
34:   'node_modules',
35:   '@magpie-community',
36:   'opencode-cursor-auth',
37: );
38: const NATIVE = join(PLUGIN_DIR, 'native-session.mjs');
39: const BACKUP = join(PLUGIN_DIR, 'native-session.mjs.orig-cursor-quiet');
40: const TARGET_MS = 600_000;
41: const TARGET_SEC = TARGET_MS / 1000;
42: 
43: // Either marker means "quiet already raised" — ours, or patch-magpie-quiet.ps1's.
44: const OUR_MARK = `// [cursor-quiet] quiet raised to ${TARGET_SEC}s`;
45: const PS1_MARK = '// [local patch] quiet raised';
46: 
47: // `  quiet: 240_000,` at the start of its line — not the prose in the
48: // error-message template (line ~105) or the throw (line ~143).
49: const QUIET_RE = /^(\s*quiet:\s*)[\d_]+(,*)\s*$/m;
50: 
51: export const statusQuiet = () => {
52:   if (!existsSync(NATIVE)) return 'missing';
53:   const src = readFileSync(NATIVE, 'utf8');
54:   if (src.includes(OUR_MARK) || src.includes(PS1_MARK)) return 'patched';
55:   if (QUIET_RE.test(src)) return 'pristine';
56:   return 'unknown';
57: };
58: 
59: export const applyQuiet = ({ force = false } = {}) => {
60:   const state = statusQuiet();
61:   if (state === 'missing') throw new Error(`native-session.mjs not found at ${PLUGIN_DIR}`);
62:   if (state === 'unknown') throw new Error('native-session.mjs layout changed; refusing to patch quiet');
63:   const src = readFileSync(NATIVE, 'utf8');
64:   const m = src.match(QUIET_RE);
65:   const currentMs = m ? Number(m[2].replace(/_/g, '')) : null;
66:   if (state === 'patched' && !force) return { changed: false, version: 'patched' };
67:   if (currentMs === TARGET_MS && !force) return { changed: false, version: `already ${TARGET_SEC}s` };
68:   if (!existsSync(BACKUP)) copyFileSync(NATIVE, BACKUP);
69:   const formatted = TARGET_MS.toLocaleString('en-US').replace(/,/g, '_'); // 600_000
70:   const patched = src.replace(QUIET_RE, `$1${formatted}$3 ${OUR_MARK}`);
71:   if (patched === src) throw new Error('quiet assignment not found');
72:   const tmp = `${NATIVE}.tmp-cursor-quiet`;
73:   writeFileSync(tmp, patched);
74:   renameSync(tmp, NATIVE);
75:   try {
76:     execSync(`node --check "${NATIVE}"`, { stdio: 'pipe' });
77:   } catch {
78:     // syntax check is best-effort; patch-magpie-quiet.ps1 does a full import verify
79:   }
80:   return { changed: true, from: currentMs, to: TARGET_MS };
81: };
82: 
83: export const restoreQuiet = () => {
84:   if (!existsSync(BACKUP)) throw new Error('no backup to restore (native-session.mjs.orig-cursor-quiet)');
85:   copyFileSync(BACKUP, NATIVE);
86:   try {
87:     execSync(`node --check "${NATIVE}"`, { stdio: 'pipe' });
88:   } catch {
89:     /* best-effort */
90:   }
91:   return { restored: true };
