// Proves the batch-sealed patch changes exactly what it claims:
//   * a retransmitted exec whose identity is already in the sealed batch is
//     dropped instead of ending the turn;
//   * a genuinely new exec while awaiting results still fails exactly as before;
//   * a terminal session still fails for anything.
// Loads the REAL patched plugin module and drives its acceptCall directly.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { NATIVE } from './patch-batch-sealed.mjs';
import { pathToFileURL } from 'node:url';

const mod = await import(pathToFileURL(NATIVE).href);

// Minimal stand-ins for the collaborators acceptCall touches.
const makeSession = (state, terminal = false) => {
  const sealed = {
    calls: [],
  };
  const s = {
    terminal,
    state,
    segments: 1,
    said: 0,
    execs: new Map(),
    nativeCalls: new Map(),
    identity: 'test',
    segment: { calls: [] },
    batches: [sealed],
    retain() {},
    execClose() {},
    waitForBatch() {},
    sealBatch() {},
  };
  return s;
};

// digest is computed inside acceptCall from the call itself, so a retransmission
// is a call object with identical fields.
const call = (over = {}) => ({
  requestID: 7,
  execID: 'exec-1',
  nativeID: 'native-1',
  name: 'mcp_gateway',
  args: [{ server: 'dbx' }],
  ...over,
});

const seed = (s, c) => {
  // emulate what the upstream does on first accept: record the call in the
  // sealed batch with the digest acceptCall derives.
  s.__probe = c;
};

test('retransmission of a call already in the sealed batch is dropped', () => {
  const s = makeSession('awaiting-results');
  const c = call();
  // First: put the identical call into the sealed batch the way sealBatch does.
  // acceptCall cannot do it (it returns early when awaiting-results), so the
  // batch is seeded with the call + its digest as the original accept left it,
  // then the retransmission arrives.
  const proto = Object.getPrototypeOf(s);
  // seed via a pristine-shaped accept into a running state
  const original = mod.NativeSession?.prototype?.acceptCall;
  // Instead of guessing digest internals, run acceptCall once in a running
  // state to produce the recorded call, then re-enter in awaiting-results.
  s.state = 'running';
  const realAccept = NativeSessionAccept(mod, s);
  realAccept(c);
  const recorded = s.execs.get(c.requestID);
  assert.ok(recorded, 'first accept must record the exec');
  s.batches[0].calls.push(recorded);
  s.state = 'awaiting-results';
  s.execs.delete(c.requestID); // simulate the dropped first copy
  assert.doesNotThrow(() => realAccept(call()), 'a retransmission must not end the turn');
});

test('a genuinely new exec while awaiting results still fails', () => {
  const s = makeSession('awaiting-results');
  const realAccept = NativeSessionAccept(mod, s);
  assert.throws(() => realAccept(call({ requestID: 99 })), /native call arrived after its batch was sealed/);
});

test('terminal session still rejects any call', () => {
  const s = makeSession('running', true);
  const realAccept = NativeSessionAccept(mod, s);
  assert.throws(() => realAccept(call()), /native call arrived after its batch was sealed/);
});

// Pull acceptCall off the exported prototype if available; otherwise reuse the
// patched source through a tiny shim so the assertions stay on real code.
function NativeSessionAccept(m, s) {
  const cls = m.NativeSession || m.default?.NativeSession;
  if (cls?.prototype?.acceptCall) return cls.prototype.acceptCall.bind(s);
  throw new Error('NativeSession.prototype.acceptCall not exported from plugin');
}

// Verifies the batch-sealed patch on the REAL installed plugin file.
//
// NativeSession is not exported by the plugin, so this asserts two things that
// together define the fix:
//   1. the patched source shape: the sealed-phase guard is split into a terminal
//      check plus an awaiting-results check that first looks for a matching call
//      in the sealed batch and returns on a hit;
//   2. the extracted guard logic behaves correctly when executed: an identical
//      retransmission returns (turn survives), a new exec throws, terminal throws.
//
//   node --test batch-sealed.test.mjs
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { NATIVE } from './patch-batch-sealed.mjs';

const src = readFileSync(NATIVE, 'utf8');

const invalid = (message, status = 409) => {
  throw Object.assign(new Error(message), { status });
};

// Mirror of the patched guard, kept structurally identical to the file.
const guard = (session, call, digest) => {
  if (session.terminal) invalid('native call arrived after its batch was sealed', 502);
  if (session.state === 'awaiting-results') {
    const sealed = session.batches?.find((b) => b.calls.some((c) => c.requestID === call.requestID && c.digest === digest));
    if (sealed) return 'dropped';
    invalid('native call arrived after its batch was sealed', 502);
  }
  return 'accepted';
};

test('installed plugin carries the patched sealed-phase guard', () => {
  assert.match(src, /\[cursor-batch-sealed\]/);
  assert.match(src, /if \(this\.terminal\) invalid\("native call arrived after its batch was sealed", 502\)/);
  assert.match(src, /const sealed = this\.batches\?\.find/);
  // the unpatched combined guard must be gone
  assert.doesNotMatch(src, /if \(this\.terminal \|\| this\.state === "awaiting-results"\) invalid\("native call arrived after its batch was sealed", 502\)/);
});

test('retransmission already sealed into the batch is dropped, not fatal', () => {
  const session = {
    terminal: false,
    state: 'awaiting-results',
    batches: [{ calls: [{ requestID: 7, digest: 'aaa' }] }],
  };
  assert.equal(guard(session, { requestID: 7 }, 'aaa'), 'dropped');
});

test('a genuinely new exec while awaiting results still fails', () => {
  const session = {
    terminal: false,
    state: 'awaiting-results',
    batches: [{ calls: [{ requestID: 7, digest: 'aaa' }] }],
  };
  assert.throws(() => guard(session, { requestID: 99 }, 'bbb'), /batch was sealed/);
});

test('same request ID with a different digest still fails (identity changed)', () => {
  const session = {
