// Adds the cursor batch-sealed root cause to OpenViking via the ov CLI.
// Node passes argv directly (no PowerShell quoting/re-encoding), and the
// content is read as UTF-8 so Chinese survives.
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { join } from 'node:path';
import { homedir } from 'node:os';

const note = join(homedir(), '.dsh', 'patches', 'cursor-batch-sealed', 'memory-note.txt');
const content = readFileSync(note, 'utf8');
const payload = JSON.stringify({ role: 'user', content });

const out = execFileSync('ov', ['add-memory', payload, '-o', 'json'], {
  encoding: 'utf8',
  maxBuffer: 32 * 1024 * 1024,
  env: { ...process.env },
});
console.log(out.slice(0, 2000));
